"""Separate SQLite namespace: never migrate a legacy Bumi database implicitly."""
APPLICATION_ID = 0x42554D31  # BUM1
SCHEMA_VERSION = 1001       # Deliberately > legacy Bumi's supported version 2.
SCHEMA = """
CREATE TABLE principals(person_id TEXT PRIMARY KEY, display_name TEXT NOT NULL);
CREATE TABLE spaces(space_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES principals(person_id), created_at REAL NOT NULL);
CREATE TABLE memberships(space_id TEXT NOT NULL REFERENCES spaces(space_id), person_id TEXT NOT NULL REFERENCES principals(person_id), status TEXT NOT NULL CHECK(status IN ('active','removed')), PRIMARY KEY(space_id,person_id));
CREATE TABLE relations(space_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, relation TEXT NOT NULL, PRIMARY KEY(space_id,source_id,target_id,relation), FOREIGN KEY(space_id,source_id) REFERENCES memberships(space_id,person_id), FOREIGN KEY(space_id,target_id) REFERENCES memberships(space_id,person_id));
CREATE TABLE conversations(conversation_id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(space_id), owner_id TEXT NOT NULL REFERENCES principals(person_id), created_at REAL NOT NULL);
CREATE TABLE conversation_members(conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), person_id TEXT NOT NULL REFERENCES principals(person_id), PRIMARY KEY(conversation_id,person_id));
CREATE TABLE observations(observation_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), space_id TEXT NOT NULL REFERENCES spaces(space_id), owner_id TEXT NOT NULL REFERENCES principals(person_id), speaker_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')), audience_json TEXT NOT NULL, current_revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','withdrawn')), created_at REAL NOT NULL, expires_at REAL NOT NULL);
CREATE TABLE observation_versions(observation_id TEXT NOT NULL REFERENCES observations(observation_id), revision INTEGER NOT NULL, text TEXT NOT NULL, content_hash TEXT NOT NULL, source_timestamp REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','superseded','withdrawn')), PRIMARY KEY(observation_id,revision));
CREATE TABLE conversation_turns(turn_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id), sequence_no INTEGER NOT NULL, observation_id TEXT NOT NULL, revision INTEGER NOT NULL, context_only INTEGER NOT NULL DEFAULT 0, source_turn_id TEXT, UNIQUE(conversation_id,sequence_no), UNIQUE(conversation_id,source_turn_id), FOREIGN KEY(observation_id,revision) REFERENCES observation_versions(observation_id,revision));
CREATE TABLE source_spans(span_id TEXT PRIMARY KEY, observation_id TEXT NOT NULL, revision INTEGER NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL CHECK(end_offset>start_offset), quote_hash TEXT NOT NULL, UNIQUE(observation_id,revision,start_offset,end_offset), FOREIGN KEY(observation_id,revision) REFERENCES observation_versions(observation_id,revision));
CREATE TABLE memories(memory_id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(space_id), owner_id TEXT NOT NULL REFERENCES principals(person_id), kind TEXT NOT NULL CHECK(kind IN ('identity','behavior','episode','record_index')), subjects_json TEXT NOT NULL, fact_key TEXT, current_version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('candidate','active','contested','deleted')), created_at REAL NOT NULL, expires_at REAL NOT NULL);
CREATE INDEX memory_owner_kind ON memories(space_id,owner_id,kind,state);
CREATE INDEX memory_fact_key ON memories(space_id,owner_id,fact_key);
CREATE TABLE memory_versions(memory_id TEXT NOT NULL REFERENCES memories(memory_id), version INTEGER NOT NULL, payload_json TEXT NOT NULL, assertion_kind TEXT NOT NULL, validity_status TEXT NOT NULL CHECK(validity_status IN ('valid','corrected','withdrawn')), valid_from REAL NOT NULL, valid_until REAL, created_at REAL NOT NULL, reason TEXT NOT NULL, PRIMARY KEY(memory_id,version), CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE TABLE version_spans(memory_id TEXT NOT NULL, version INTEGER NOT NULL, span_id TEXT NOT NULL REFERENCES source_spans(span_id), PRIMARY KEY(memory_id,version,span_id), FOREIGN KEY(memory_id,version) REFERENCES memory_versions(memory_id,version));
CREATE INDEX evidence_from_span ON version_spans(span_id);
CREATE TABLE parent_edges(memory_id TEXT NOT NULL, version INTEGER NOT NULL, parent_id TEXT NOT NULL, parent_version INTEGER NOT NULL, attributes_json TEXT NOT NULL, PRIMARY KEY(memory_id,version,parent_id,parent_version), FOREIGN KEY(memory_id,version) REFERENCES memory_versions(memory_id,version), FOREIGN KEY(parent_id,parent_version) REFERENCES memory_versions(memory_id,version));
CREATE INDEX evidence_from_parent ON parent_edges(parent_id,parent_version);
CREATE TABLE grants(grant_id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(space_id), subject_id TEXT NOT NULL REFERENCES principals(person_id), audience_json TEXT NOT NULL, effect TEXT NOT NULL CHECK(effect IN ('allow','deny')), category TEXT NOT NULL, attributes_json TEXT NOT NULL, purposes_json TEXT NOT NULL, target_memory_id TEXT REFERENCES memories(memory_id), block_inference INTEGER NOT NULL, starts_at REAL NOT NULL, expires_at REAL, status TEXT NOT NULL CHECK(status IN ('active','revoked')));
CREATE INDEX grants_by_space_subject ON grants(space_id,subject_id,status);
CREATE TABLE memory_views(view_id TEXT PRIMARY KEY, memory_id TEXT NOT NULL, source_version INTEGER NOT NULL, view_revision INTEGER NOT NULL, snapshot_kind TEXT NOT NULL CHECK(snapshot_kind IN ('current','historical')), projection_type TEXT NOT NULL, attributes_json TEXT NOT NULL, audience_json TEXT NOT NULL, purposes_json TEXT NOT NULL, projected_json TEXT NOT NULL, display_text TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','invalidated')), created_at REAL NOT NULL, FOREIGN KEY(memory_id,source_version) REFERENCES memory_versions(memory_id,version));
CREATE INDEX views_by_memory ON memory_views(memory_id,source_version,status);
CREATE TABLE scope_epochs(space_id TEXT PRIMARY KEY REFERENCES spaces(space_id), content INTEGER NOT NULL DEFAULT 0, policy INTEGER NOT NULL DEFAULT 0, deletion INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audit_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, space_id TEXT, actor_id TEXT, operation TEXT NOT NULL, object_id TEXT, created_at REAL NOT NULL);
"""
